import{_ as t,o,c as n,a6 as r}from"./chunks/framework.QBF2cGGQ.js";const c=JSON.parse('{"title":"25 · Agent Harness 与 Loop Engineering","description":"","frontmatter":{},"headers":[],"relativePath":"guide/25-harness-loop.md","filePath":"guide/25-harness-loop.md","lastUpdated":1793330726000}'),a={name:"guide/25-harness-loop.md"};function i(e,s,g,l,p,u){return o(),n("div",null,[...s[0]||(s[0]=[r('<h1 id="_25-·-agent-harness-与-loop-engineering" tabindex="-1">25 · Agent Harness 与 Loop Engineering <a class="header-anchor" href="#_25-·-agent-harness-与-loop-engineering" aria-label="Permalink to &quot;25 · Agent Harness 与 Loop Engineering&quot;">​</a></h1><blockquote><p><strong>投入权重：8%</strong> · 新增一章。<strong>这一章讲的是 Codex、Claude Code、Cursor Agent 这类系统背后的运行机制</strong>，不是&quot;怎么用它们&quot;。</p><p>行业终于给两件事起了名字，而这两件事你其实已经学了一半：<strong>Harness 是模型外面那套让它能可靠干活的壳，Loop 是它迭代收敛的那个圈。</strong> 但名字一旦出现，面试就会用名字问。这一章把词和内容对上。</p></blockquote><h2 id="一个公式先记住" tabindex="-1">一个公式先记住 <a class="header-anchor" href="#一个公式先记住" aria-label="Permalink to &quot;一个公式先记住&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent = Model + Harness</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><strong>Model 提供</strong>：理解、推理、生成、决策建议。<strong>它是商品</strong>——你可以换，而且大家用的是同几家。</li><li><strong>Harness 提供</strong>：工具、状态、权限、执行、反馈。<strong>它是你的产品</strong>——同样的模型，Harness 不同，能干的活差一个数量级。</li></ul><p><strong>这句话是整个 2026 年 Agent 工程的认知起点</strong>：模型能力趋同，差异化全在壳上。所以面试问&quot;你们 Agent 的核心竞争力&quot;，答&quot;我们用了 GPT-5&quot;是零分，答&quot;我们的工具设计、状态管理和验证回路&quot;才是分数。</p><h2 id="harness-是什么-一句话版" tabindex="-1">Harness 是什么（一句话版） <a class="header-anchor" href="#harness-是什么-一句话版" aria-label="Permalink to &quot;Harness 是什么（一句话版）&quot;">​</a></h2><p><strong>Harness = 把一个只会说话的模型，变成能改真实世界的系统的全部工程。</strong></p><p>它包含六件事：<strong>能看什么（上下文）、能做什么（工具）、允许做什么（权限）、做过什么（状态）、做得对不对（验证）、出错怎么办（恢复）</strong>。下面逐项拆。</p><h3 id="运行时-runtime" tabindex="-1">运行时（Runtime） <a class="header-anchor" href="#运行时-runtime" aria-label="Permalink to &quot;运行时（Runtime）&quot;">​</a></h3><ul><li><strong>Agent Runtime</strong> <span class="prio prio-must">必须</span> — 承载 Agent 循环的进程/服务。它管三件事：<strong>调度循环、分发工具调用、维护会话状态</strong>。区别于&quot;调一次 API&quot;——Runtime 是常驻的。</li><li><strong>Tool Execution Runtime</strong> <span class="prio prio-must">必须</span> — 工具不是函数调用那么简单：要<strong>并发控制、超时、重试、结果截断、错误标准化</strong>。<strong>工具执行层写不好，Agent 会因为一个慢工具整体卡死</strong>。</li><li><strong>执行隔离</strong> <span class="prio prio-must">必须</span> — 每个工具调用应该在受控环境里跑（容器 / 子进程 / 沙箱），<strong>不能和主进程共享内存和文件系统</strong>。</li><li><strong>并发与串行</strong> <span class="prio prio-imp">重要</span> — 无依赖工具并行，有依赖的串行。<strong>Runtime 要能判断依赖</strong>（通常靠模型声明，所以工具 schema 里要写清前置条件）。</li></ul><h3 id="沙箱与文件系统" tabindex="-1">沙箱与文件系统 <a class="header-anchor" href="#沙箱与文件系统" aria-label="Permalink to &quot;沙箱与文件系统&quot;">​</a></h3><ul><li><strong>Agent Sandbox</strong> <span class="prio prio-must">必须</span> — 代码执行必须隔离。四道约束：<strong>无网络（默认）、资源配额、执行超时、只读根文件系统</strong>。详见 <a href="/ai-eng-roadmap/guide/09-security">09 · 安全</a>。</li><li><strong>Virtual Filesystem（虚拟文件系统）</strong> <span class="prio prio-must">必须</span> — <strong>这是 Codex / Claude Code 类系统的核心设计</strong>：给 Agent 一个&quot;看起来像文件系统&quot;的工作区，实际上可能是数据库、对象存储或内存。好处有三个：① 模型天然会用文件（训练数据里全是）② 大块内容可以&quot;写出去&quot;，不用一直占上下文 ③ 状态可持久化、可回放。</li><li><strong>工作区布局要稳定</strong> <span class="prio prio-imp">重要</span> — <code>/workspace/input</code>（只读输入）、<code>/workspace/scratch</code>（草稿）、<code>/workspace/output</code>（产出）。<strong>固定布局让模型的成功率显著上升</strong>，因为它能形成稳定预期。</li><li><strong>文件即状态</strong> <span class="prio prio-imp">重要</span> — 长任务的中间结果写文件，不留在对话里。<strong>这是&quot;能做几小时任务&quot;和&quot;只能做十分钟任务&quot;的分界线</strong>。</li></ul><h3 id="上下文管理" tabindex="-1">上下文管理 <a class="header-anchor" href="#上下文管理" aria-label="Permalink to &quot;上下文管理&quot;">​</a></h3><ul><li><strong>Context Offloading（上下文卸载）</strong> <span class="prio prio-must">必须</span> — 把大块内容挪出上下文，只留一个&quot;句柄&quot;（文件路径、记录 ID）。<strong>模型需要时再读回来</strong>。典型：抓到的网页写进文件，上下文里只留&quot;已保存到 /scratch/page1.md，共 3200 字&quot;。</li><li><strong>Context Compaction（上下文压缩）</strong> <span class="prio prio-must">必须</span> — 上下文快满时，把前面的对话压成摘要，保留关键结论和未完成事项。<strong>和 <a href="/ai-eng-roadmap/guide/22-memory">22 · 记忆</a> 的滚动摘要同源，但目标是&quot;不中断当前任务&quot;而不是&quot;跨会话记住&quot;</strong>。</li><li><strong>压缩的时机</strong> <span class="prio prio-imp">重要</span> — 不要等到 100%。<strong>经验值：到窗口的 70~80% 就开始压</strong>，因为压缩本身要花 token，而且压完还要留空间继续干活。</li><li><strong>压缩会丢什么</strong> <span class="prio prio-imp">重要</span> — 容易丢&quot;限定词&quot;（除了…、只在…时、不要…）。<strong>所以&quot;约束条件&quot;要单独结构化存一份，不参与压缩</strong>。</li><li><strong>Memory Management（记忆管理）</strong> <span class="prio prio-must">必须</span> — Harness 要区分三层：<strong>当前任务的工作记忆、跨轮次的会话记忆、跨会话的长期记忆</strong>。见 <a href="/ai-eng-roadmap/guide/22-memory">22 章</a>。</li><li><strong>Skills Loading（技能按需加载）</strong> <span class="prio prio-must">必须</span> — 不把所有能力塞进 system prompt，而是<strong>先给目录、需要时加载全文</strong>。这是 Skill 相对&quot;全塞进去&quot;的核心优势（渐进披露）。</li><li><strong>上下文预算的显式分配</strong> <span class="prio prio-must">必须</span> — system / 工具定义 / 检索结果 / 历史 / 输出预留，<strong>五份抢一个池子，必须写死比例</strong>。不分配就会某一项吃掉全部。</li></ul><h3 id="任务与委派" tabindex="-1">任务与委派 <a class="header-anchor" href="#任务与委派" aria-label="Permalink to &quot;任务与委派&quot;">​</a></h3><ul><li><strong>Task Planning（任务规划）</strong> <span class="prio prio-must">必须</span> — 把目标拆成可验证的步骤，写成结构化列表（不是自然语言段落）。<strong>能勾选完成的列表，比&quot;我认为应该这样做&quot;可靠得多</strong>。</li><li><strong>计划要能被修改</strong> <span class="prio prio-imp">重要</span> — 执行中发现计划错了要能改。<strong>&quot;计划不可变&quot;是常见设计错误</strong>——它会让 Agent 硬着头皮走错路。</li><li><strong>Subagent Delegation（子 Agent 委派）</strong> <span class="prio prio-must">必须</span> — 把独立子任务交给子 Agent，<strong>子 Agent 有自己干净的上下文</strong>。这是多 Agent 唯一稳定的收益来源：<strong>上下文隔离</strong>，不是&quot;更聪明&quot;。</li><li><strong>委派的成本</strong> <span class="prio prio-imp">重要</span> — 每个子 Agent 都要重新建立上下文，<strong>简单任务委派反而更慢更贵</strong>。判断标准：子任务是否&quot;需要读大量材料但只需要返回结论&quot;。</li><li><strong>委派深度限制</strong> <span class="prio prio-must">必须</span> — 子 Agent 再分子 Agent，会指数级爆炸。<strong>硬限制深度（通常 2 层）</strong>。</li></ul><h3 id="权限与人机边界" tabindex="-1">权限与人机边界 <a class="header-anchor" href="#权限与人机边界" aria-label="Permalink to &quot;权限与人机边界&quot;">​</a></h3><ul><li><strong>Execution Permissions（执行权限）</strong> <span class="prio prio-must">必须</span> — 分档授权：只读 / 可写文件 / 可执行命令 / 可访问网络 / 可触达外部系统。<strong>默认最小，逐级申请</strong>。见 <a href="/ai-eng-roadmap/guide/24-ai-assisted-dev">24 章的四档权限</a>。</li><li><strong>权限要在工具层强制</strong> <span class="prio prio-must">必须</span> — 不能靠 prompt 说&quot;不要删文件&quot;。<strong>代码里没有这个工具，它就不可能删</strong>。</li><li><strong>Human-in-the-loop（人工介入）</strong> <span class="prio prio-must">必须</span> — 三种形态：<strong>事前审批</strong>（高风险动作前问）、<strong>事中打断</strong>（发现跑偏立刻停）、<strong>事后确认</strong>（产出由人验收）。<strong>三种都要有，只做一种不够</strong>。</li><li><strong>审批的粒度</strong> <span class="prio prio-imp">重要</span> — 每个动作都问会烦死人，从不问会出事。<strong>按&quot;可逆性 × 影响范围&quot;分级</strong>：可逆且局部 → 自动；不可逆或对外 → 必须问。</li><li><strong>审批要能&quot;记住这次选择&quot;</strong> <span class="prio prio-opt">选学</span> — &quot;本次会话内不再询问同类操作&quot;。<strong>体验细节，但决定用户会不会一直开着 Agent</strong>。</li></ul><h3 id="状态与恢复" tabindex="-1">状态与恢复 <a class="header-anchor" href="#状态与恢复" aria-label="Permalink to &quot;状态与恢复&quot;">​</a></h3><ul><li><strong>State Persistence（状态持久化）</strong> <span class="prio prio-must">必须</span> — 状态必须能序列化成 JSON 落盘。<strong>只在内存里的状态 = 重启就丢</strong>。</li><li><strong>Checkpoint Recovery（检查点恢复）</strong> <span class="prio prio-must">必须</span> — 每个节点执行完存一次，失败从上个检查点继续。<strong>配套必须有幂等键</strong>，否则恢复会重复执行副作用。</li><li><strong>恢复要能答三个问题</strong> <span class="prio prio-must">必须</span> — 已做了什么、还剩什么、有没有副作用已经发生。<strong>答不出第三个，恢复就是危险的</strong>。</li><li><strong>状态版本兼容</strong> <span class="prio prio-imp">重要</span> — 加 <code>schema_version</code> + 迁移函数。<strong>跑几小时的任务一定会跨代码版本</strong>。</li></ul><h3 id="观测与评测" tabindex="-1">观测与评测 <a class="header-anchor" href="#观测与评测" aria-label="Permalink to &quot;观测与评测&quot;">​</a></h3><ul><li><strong>Trace / Debugging</strong> <span class="prio prio-must">必须</span> — 每一步的输入、输出、耗时、token、工具调用参数都要记。<strong>不能回放的 Agent 无法排障</strong>。见 <a href="/ai-eng-roadmap/guide/08-observability">08 · 可观测</a>。</li><li><strong>Evaluation Harness（评测脚手架）</strong> <span class="prio prio-must">必须</span> — 能批量跑任务、能对比版本、能给出&quot;这次改动是变好还是变坏&quot;。<strong>Harness 里没有评测，你就永远在盲改</strong>。见 <a href="/ai-eng-roadmap/guide/07-evals">07 · 评测</a>。</li><li><strong>成本与步数归因</strong> <span class="prio prio-imp">重要</span> — 每次任务花了多少 token、多少钱、多少步。<strong>没有归因就不知道钱花在哪个环节</strong>。</li></ul><h2 id="loop-engineering-循环怎么设计" tabindex="-1">Loop Engineering：循环怎么设计 <a class="header-anchor" href="#loop-engineering-循环怎么设计" aria-label="Permalink to &quot;Loop Engineering：循环怎么设计&quot;">​</a></h2><p>Harness 是&quot;壳&quot;，Loop 是&quot;心跳&quot;。<strong>模型再强，循环设计错了也收敛不了。</strong></p><h3 id="四拍循环" tabindex="-1">四拍循环 <a class="header-anchor" href="#四拍循环" aria-label="Permalink to &quot;四拍循环&quot;">​</a></h3><ul><li><strong>Observe → Act → Evaluate → Adjust</strong> <span class="prio prio-must">必须</span> — 观察（看到什么）→ 行动（做什么）→ 评估（结果对不对）→ 调整（下一步改什么）。<strong>ReAct 是它的简化版</strong>（少了显式的 Evaluate）。</li><li><strong>Evaluate 是大多数人漏掉的一拍</strong> <span class="prio prio-must">必须</span> — 只做 Observe-Act 就是&quot;瞎试&quot;。<strong>必须有独立的评估步骤</strong>：这个结果算成功吗？为什么？<strong>很多 Agent demo 失败就失败在&quot;没有评估，只有下一步&quot;</strong>。</li><li><strong>评估要客观</strong> <span class="prio prio-must">必须</span> — 测试通过、编译成功、字段齐全、断言成立。<strong>&quot;模型自己说做完了&quot;不算评估</strong>。</li><li><strong>评估结果结构化</strong> <span class="prio prio-imp">重要</span> — 输出 <code>{passed: bool, reason: string, next_hint: string}</code>，而不是一段散文。<strong>结构化的评估才能驱动下一步</strong>。</li></ul><h3 id="终止条件" tabindex="-1">终止条件 <a class="header-anchor" href="#终止条件" aria-label="Permalink to &quot;终止条件&quot;">​</a></h3><ul><li><strong>迭代终止条件</strong> <span class="prio prio-must">必须</span> — 四个都要有：<strong>成功终止</strong>（评估通过）、<strong>步数上限</strong>、<strong>成本上限</strong>、<strong>无进展检测</strong>。少一个就可能烧钱。</li><li><strong>成功判定要写死</strong> <span class="prio prio-must">必须</span> — &quot;看起来差不多了&quot;不是判定。<strong>必须是可执行断言</strong>：测试全绿 / 输出匹配 schema / 文件存在且非空。</li><li><strong>任务进度判断</strong> <span class="prio prio-imp">重要</span> — 用&quot;计划列表里已完成项数&quot;而不是&quot;感觉在推进&quot;。<strong>进度不涨就是卡住了</strong>。</li><li><strong>无效循环检测</strong> <span class="prio prio-must">必须</span> — 三个信号：<strong>相同动作重复</strong>（同参数调同一工具）、<strong>相同错误重复</strong>（同样的报错出现三次）、<strong>状态无变化</strong>（文件没变、测试结果没变）。<strong>任一触发就该停</strong>。</li><li><strong>停下来之后做什么</strong> <span class="prio prio-imp">重要</span> — 不是直接报错，而是<strong>降级</strong>：给出半成品 + 说清卡在哪 + 建议人接手。<strong>这比&quot;任务失败&quot;体验好一个量级</strong>。</li></ul><h3 id="修复循环" tabindex="-1">修复循环 <a class="header-anchor" href="#修复循环" aria-label="Permalink to &quot;修复循环&quot;">​</a></h3><ul><li><strong>错误修复循环</strong> <span class="prio prio-must">必须</span> — 读报错 → 定位 → 假设原因 → 改一处 → 重跑。<strong>关键是&quot;改一处&quot;</strong>，一次改五处就不知道哪个生效了。</li><li><strong>同一处失败三次就停</strong> <span class="prio prio-must">必须</span> — 硬规则。<strong>连续失败说明理解错了，继续试只是烧钱</strong>。停下来重新给上下文，比试十次有效。</li><li><strong>自我验证（Self-verification）</strong> <span class="prio prio-must">必须</span> — 提交前自己检查一遍：改的文件对吗？有没有漏改调用方？有没有引入新依赖？<strong>这一步能拦掉三成低级错误</strong>。</li><li><strong>测试驱动迭代</strong> <span class="prio prio-must">必须</span> — 先有测试，循环才有客观信号。<strong>没有测试的 Agentic 循环，等于没有方向盘</strong>。</li></ul><h3 id="预算与性能" tabindex="-1">预算与性能 <a class="header-anchor" href="#预算与性能" aria-label="Permalink to &quot;预算与性能&quot;">​</a></h3><ul><li><strong>资源预算控制</strong> <span class="prio prio-must">必须</span> — 每次任务设 token 预算、时间预算、工具调用次数预算。<strong>超预算降级，不要硬跑</strong>。</li><li><strong>循环性能评测</strong> <span class="prio prio-imp">重要</span> — 指标：<strong>平均步数、平均成本、成功率、首次成功率、人工接管率</strong>。<strong>&quot;平均步数下降&quot;通常比&quot;成功率上升&quot;更能说明优化有效</strong>。</li><li><strong>收敛速度</strong> <span class="prio prio-imp">重要</span> — 同样的任务，8 步做完和 20 步做完，成本差 2.5 倍。<strong>优化步数是降本最直接的手段</strong>。</li><li><strong>过度循环</strong> <span class="prio prio-imp">重要</span> — 已经成功了还在&quot;优化&quot;。<strong>成功判定一旦通过就退出，不要贪心</strong>。</li></ul><h2 id="deep-agents-一个具体的-harness-实现" tabindex="-1">Deep Agents：一个具体的 Harness 实现 <a class="header-anchor" href="#deep-agents-一个具体的-harness-实现" aria-label="Permalink to &quot;Deep Agents：一个具体的 Harness 实现&quot;">​</a></h2><p>LangChain 的 Deep Agents 是<strong>目前最容易看懂的完整 Harness 参考实现</strong>，而且有 <strong>JavaScript/TypeScript 版本</strong>——对你来说这是最值得读的一份源码。</p><p>它把六件事组合在一起，正好对应上面 Harness 的六块：</p><table tabindex="0"><thead><tr><th>能力</th><th>对应 Harness 组件</th><th>解决什么问题</th></tr></thead><tbody><tr><td><strong>任务规划</strong>（todo list 工具）</td><td>Task Planning</td><td>长任务不跑偏，进度可见</td></tr><tr><td><strong>虚拟文件系统</strong></td><td>Virtual Filesystem</td><td>大块内容卸载，状态可持久</td></tr><tr><td><strong>上下文管理</strong>（自动压缩 + 卸载）</td><td>Context Compaction / Offloading</td><td>能做几小时任务</td></tr><tr><td><strong>子 Agent 委派</strong></td><td>Subagent Delegation</td><td>隔离上下文，并行</td></tr><tr><td><strong>记忆</strong></td><td>Memory Management</td><td>跨轮次记住</td></tr><tr><td><strong>人工审批</strong></td><td>Human-in-the-loop</td><td>高风险动作可控</td></tr></tbody></table><ul><li><strong>为什么值得读</strong> <span class="prio prio-must">必须</span> — 它把这些能力<strong>做成了一套可组合的原语</strong>，而不是一个大框架。<strong>读它能理解&quot;Codex 那类系统是怎么搭出来的&quot;</strong>。</li><li><strong>和 LangGraph 的关系</strong> <span class="prio prio-imp">重要</span> — LangGraph 是底层图执行引擎，Deep Agents 是<strong>在它之上封装的&quot;开箱即用 Harness&quot;</strong>。<strong>理解分层比记名字重要</strong>。</li><li><strong>可以直接抄的设计</strong> <span class="prio prio-must">必须</span> — ① 规划用 todo 工具而不是让模型自由发挥 ② 大文件写进虚拟 FS ③ 子 Agent 只回传结论 ④ 审批点挂在工具层。<strong>这四条抄过来就能用</strong>。</li><li><strong>别只学它</strong> <span class="prio prio-imp">重要</span> — 它是参考实现，不是唯一答案。<strong>你的业务场景（比如审批流、多租户、私有化）它没有覆盖</strong>，要自己加。</li></ul><h2 id="为什么这一章比-学框架-值钱" tabindex="-1">为什么这一章比&quot;学框架&quot;值钱 <a class="header-anchor" href="#为什么这一章比-学框架-值钱" aria-label="Permalink to &quot;为什么这一章比&quot;学框架&quot;值钱&quot;">​</a></h2><ul><li><strong>框架会换，机制不会</strong> <span class="prio prio-must">必须</span> — LangChain 三年换了三个抽象，但&quot;工具执行要超时&quot;这件事永远成立。<strong>学机制的人换框架只需一周，学框架的人换框架等于重来</strong>。</li><li><strong>面试的分水岭</strong> <span class="prio prio-must">必须</span> — 问&quot;你怎么做的 Agent&quot;，答&quot;用 LangGraph 串了几个节点&quot;是初级；答&quot;我们自己实现了上下文卸载、检查点恢复和无效循环检测，因为框架在这三块不够用&quot;——<strong>这是能做 Codex 类系统的人</strong>。</li><li><strong>你的前端经验在这里有用</strong> <span class="prio prio-imp">重要</span> — 虚拟文件系统像前端的虚拟 DOM，上下文卸载像前端的虚拟列表，检查点恢复像前端的草稿保存。<strong>这些类比不是巧合，都是&quot;用一层间接把昂贵资源管起来&quot;</strong>。</li></ul><h2 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h2><ul><li>能用一句话说清 <code>Agent = Model + Harness</code>，并解释为什么差异化在 Harness</li><li>能列出 Harness 的六块（上下文 / 工具 / 权限 / 状态 / 验证 / 恢复），每块举一个具体组件</li><li>能解释 Context Offloading 和 Context Compaction 的区别，以及各自什么时候用</li><li>能设计一个四拍循环（Observe/Act/Evaluate/Adjust），并说清 Evaluate 用什么客观信号</li><li>能说出四个终止条件，以及&quot;无效循环&quot;的三个检测信号</li><li>能画出虚拟文件系统的目录布局，并说明它解决什么问题</li><li>能读懂 Deep Agents 的核心设计，并说出哪四条可以直接抄进自己的项目</li></ul>',42)])])}const h=t(a,[["render",i]]);export{c as __pageData,h as default};
